import { useSyncExternalStore } from 'react';

// GameIcon's fit (Icons board). data/sprite-bounds.json is generated by z-processing from public/ every
// game version: [canvas width, canvas height, x0, y0, x1, y1] of the pixels a sprite draws, keyed by its
// path under public/, for each sprite that leaves part of its canvas empty. At ~530 KB it loads as its
// own chunk, once, and never sits in a page's own scripts (e2e/chunk-audit.spec.js).
let bounds = null;
let loading = null;
const listeners = new Set();

export const loadSpriteBounds = () => {
  loading ??= import('../data/sprite-bounds.json')
    .then(({ default: data }) => {
      bounds = data;
    })
    .catch(() => {
      // A chunk that failed (offline, a deploy race): no entries is the whole-canvas fit, so no icon stays
      // pending. loading resets so the next icon that mounts tries again.
      bounds ??= {};
      loading = null;
    })
    .finally(() => listeners.forEach((listener) => listener()));
  return loading;
};

// Start as soon as a page that draws game icons loads, so the bounds are usually in before its data.
if (typeof window !== 'undefined') loadSpriteBounds();

const subscribe = (listener) => {
  listeners.add(listener);
  // A no-op once loading or loaded; after a failed load, a later page's icons retry it.
  loadSpriteBounds();
  return () => listeners.delete(listener);
};

// null during the build and hydration, so the first render matches the export; icons refit once the
// bounds arrive.
export const useSpriteBounds = () => useSyncExternalStore(subscribe, () => bounds, () => null);

const FILL = 0.9;

// Where to draw a sprite in a size x size box so its drawn pixels fill FILL of the box, centered.
export const fitSprite = ([width, height, x0, y0, x1, y1], size) => {
  const drawnWidth = x1 - x0;
  const drawnHeight = y1 - y0;
  const scale = (FILL * size) / Math.max(drawnWidth, drawnHeight);
  return {
    width: width * scale,
    height: height * scale,
    left: size / 2 - (x0 + drawnWidth / 2) * scale,
    top: size / 2 - (y0 + drawnHeight / 2) * scale
  };
};

// A frame and the sprite on it share one canvas in the game, so they share one fit: the union of what
// both draw. null when either has no entry (it fills its canvas) or the canvases differ: both then take
// the whole canvas.
export const unionBounds = (a, b) => {
  if (!a || !b || a[0] !== b[0] || a[1] !== b[1]) return null;
  return [a[0], a[1], Math.min(a[2], b[2]), Math.min(a[3], b[3]), Math.max(a[4], b[4]), Math.max(a[5], b[5])];
};
